class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        si, pi = 0, 0
        star_idx, match = -1, 0
        while si < len(s):
            if pi < len(p) and (p[pi] == '?' or p[pi] == s[si]):
                si += 1; pi += 1
            elif pi < len(p) and p[pi] == '*':
                star_idx = pi; match = si; pi += 1
            elif star_idx != -1:
                pi = star_idx + 1; match += 1; si = match
            else: return False
        while pi < len(p) and p[pi] == '*': pi += 1
        return pi == len(p)

