#include <iostream>
#include <string>
#include <vector>

using namespace std;

bool isMatch(string s, string p) {
    int s_len = s.size(), p_len = p.size();
    int s_idx = 0, p_idx = 0, star_idx = -1, s_tmp_idx = -1;
    while (s_idx < s_len) {
        if (p_idx < p_len && (p[p_idx] == s[s_idx] || p[p_idx] == '?')) {
            s_idx++; p_idx++;
        } else if (p_idx < p_len && p[p_idx] == '*') {
            star_idx = p_idx;
            s_tmp_idx = s_idx;
            p_idx++;
        } else if (star_idx != -1) {
            p_idx = star_idx + 1;
            s_tmp_idx++;
            s_idx = s_tmp_idx;
        } else return false;
    }
    while (p_idx < p_len && p[p_idx] == '*') p_idx++;
    return p_idx == p_len;
}

int main() {
    string s, p;
    if (!(getline(cin, s))) return 0;
    if (!(getline(cin, p))) p = "";
    if (!s.empty() && s[0] == '"') s = s.substr(1, s.size() - 2);
    if (!p.empty() && p[0] == '"') p = p.substr(1, p.size() - 2);
    // Special case for "" input
    if (s == """") s = "";
    if (p == """") p = "";
    cout << (isMatch(s, p) ? "true" : "false") << endl;
    return 0;
}

