import java.util.*;
import java.io.*;

public class Main {
    public static boolean isMatch(String s, String p) {
        int sLen = s.length(), pLen = p.length();
        int sIdx = 0, pIdx = 0, starIdx = -1, sTmpIdx = -1;
        while (sIdx < sLen) {
            if (pIdx < pLen && (p.charAt(pIdx) == s.charAt(sIdx) || p.charAt(pIdx) == '?')) {
                sIdx++; pIdx++;
            } else if (pIdx < pLen && p.charAt(pIdx) == '*') {
                starIdx = pIdx;
                sTmpIdx = sIdx;
                pIdx++;
            } else if (starIdx != -1) {
                pIdx = starIdx + 1;
                sTmpIdx++;
                sIdx = sTmpIdx;
            } else return false;
        }
        while (pIdx < pLen && p.charAt(pIdx) == '*') pIdx++;
        return pIdx == pLen;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine(); if (s == null) s = "";
        String p = br.readLine(); if (p == null) p = "";
        s = s.trim().replace("\"", "");
        p = p.trim().replace("\"", "");
        System.out.println(isMatch(s, p));
    }
}

